{"success": true, "data": {"stdout": "import json
import re
import os
from collections import Counter

SRC_DIR = "/root/autodl-tmp/trace-verdict-study-data"
OUT_DIR = "/root/autodl-tmp/trace-verdict-study-data/exc_subcomponent"
os.makedirs(OUT_DIR, exist_ok=True)

ERROR_PAT = re.compile(
    r'\[ERROR\]\s+(\w+)\s+at\s+line\s+(\d+):\s*(.*?)\s*\|\s*locals:\s*(.*)'
)

TRACE_MARKER = "Execution trace:\n"
TAIL_MARKER = "\n\nDoes this code pass all tests?"


def extract_trace_block(inp):
    start = inp.find(TRACE_MARKER)
    if start < 0:
        return None, None, None
    trace_start = start + len(TRACE_MARKER)
    end = inp.find(TAIL_MARKER, trace_start)
    if end < 0:
        end = len(inp)
    return inp[:trace_start], inp[trace_start:end], inp[end:]


def transform_error_line(line, mode):
    m = ERROR_PAT.match(line)
    if not m:
        return line
    exc_type, lineno, message, locals_str = m.groups()
    message = message.strip()
    if mode == "exc_type_only":
        if message:
            return f"[ERROR] {exc_type}: {message}"
        else:
            return f"[ERROR] {exc_type}"
    elif mode == "exc_stacktrace_only":
        return f"[ERROR] at line {lineno} | locals: {locals_str}"
    elif mode == "exc_message_only":
        if message:
            return message
        else:
            return f"[{exc_type}]"
    return line


def transform_trace(trace_text, mode):
    lines = trace_text.split("\n")
    new_lines = [transform_error_line(l, mode) for l in lines]
    return "\n".join(new_lines)


def process_sample(sample, mode):
    inp = sample["input"]
    prefix, trace, suffix = extract_trace_block(inp)
    if prefix is None or "[ERROR]" not in trace:
        return sample
    new_trace = transform_trace(trace, mode)
    new_sample = dict(sample)
    new_sample["input"] = prefix + new_trace + suffix
    return new_sample


def process_file(src_path, split):
    samples = []
    with open(src_path) as f:
        for line in f:
            samples.append(json.loads(line.strip()))

    stats = {"total": len(samples), "fail": 0, "pass": 0,
             "has_error": 0, "no_trace": 0, "no_exc_data": 0}
    for s in samples:
        if s["output"] == "fail":
            stats["fail"] += 1
        else:
            stats["pass"] += 1
        if "[ERROR]" in s["input"]:
            stats["has_error"] += 1
        elif "[No trace available]" in s["input"]:
            stats["no_trace"] += 1
        else:
            stats["no_exc_data"] += 1

    for mode in ["exc_type_only", "exc_stacktrace_only", "exc_message_only"]:
        out_path = os.path.join(OUT_DIR, f"{mode}_{split}.jsonl")
        with open(out_path, "w") as fout:
            for s in samples:
                new_s = process_sample(s, mode)
                fout.write(json.dumps(new_s, ensure_ascii=False) + "\n")
        print(f"  Written: {out_path}")

    return stats


def show_example(mode, split):
    path = os.path.join(OUT_DIR, f"{mode}_{split}.jsonl")
    with open(path) as f:
        for line in f:
            d = json.loads(line)
            if "[ERROR]" in d["input"] or (d["output"] == "fail" and "[No trace available]" not in d["input"]):
                inp = d["input"]
                start = inp.find("Execution trace:\n")
                end = inp.find("\n\nDoes this code pass all tests?")
                trace = inp[start:end] if start >= 0 and end >= 0 else "(not found)"
                return trace[:400]
    return "(no example found)"


def compute_trace_lengths(split):
    orig_path = os.path.join(SRC_DIR, f"exception_only_{split}.jsonl")
    results = {}
    orig_lengths = []
    with open(orig_path) as f:
        for line in f:
            d = json.loads(line)
            if "[ERROR]" in d["input"]:
                prefix, trace, suffix = extract_trace_block(d["input"])
                if trace:
                    orig_lengths.append(len(trace))
    results["original"] = sum(orig_lengths) / len(orig_lengths) if orig_lengths else 0

    for mode in ["exc_type_only", "exc_stacktrace_only", "exc_message_only"]:
        path = os.path.join(OUT_DIR, f"{mode}_{split}.jsonl")
        lengths = []
        with open(path) as f:
            for line in f:
                d = json.loads(line)
                if "[ERROR]" in d["input"] or d["output"] == "fail":
                    prefix, trace, suffix = extract_trace_block(d["input"])
                    if trace and "[No trace available]" not in trace and "[No exception data" not in trace:
                        lengths.append(len(trace))
        results[mode] = sum(lengths) / len(lengths) if lengths else 0
    return results


def verify_parse_rate(split):
    orig_path = os.path.join(SRC_DIR, f"exception_only_{split}.jsonl")
    total_error_lines = 0
    parsed_error_lines = 0
    with open(orig_path) as f:
        for line in f:
            d = json.loads(line)
            inp = d["input"]
            for l in inp.split("\\n"):
                if l.startswith("[ERROR]"):
                    total_error_lines += 1
                    if ERROR_PAT.match(l):
                        parsed_error_lines += 1
    return total_error_lines, parsed_error_lines


if __name__ == "__main__":
    print("=== Processing train ===")
    train_stats = process_file(os.path.join(SRC_DIR, "exception_only_train.jsonl"), "train")
    print(f"  Stats: {train_stats}")

    print("\n=== Processing test ===")
    test_stats = process_file(os.path.join(SRC_DIR, "exception_only_test.jsonl"), "test")
    print(f"  Stats: {test_stats}")

    print("\n=== Parse rate ===")
    for split in ["train", "test"]:
        total, parsed = verify_parse_rate(split)
        print(f"  {split}: {parsed}/{total} error lines parsed ({100*parsed/total:.1f}%)" if total else f"  {split}: no error lines")

    print("\n=== Average trace length (chars, fail+error samples) ===")
    for split in ["train", "test"]:
        lengths = compute_trace_lengths(split)
        print(f"  {split}:")
        for k, v in lengths.items():
            print(f"    {k}: {v:.0f}")

    print("\n=== Example outputs (train, fail samples) ===")
    for mode in ["exc_type_only", "exc_stacktrace_only", "exc_message_only"]:
        ex = show_example(mode, "train")
        print(f"\n--- {mode} ---")
        print(ex)
